{
  "name": "color-detect-cli",
  "version": "1.0.0",
  "description": "CLI that detects terminal color support before printing colored text",
  "type": "module",
  "bin": {
    "color-detect": "./bin/cli.js"
  },
  "main": "./lib/colors.js",
  "exports": {
    ".": "./lib/colors.js"
  },
  "files": [
    "bin",
    "lib"
  ],
  "scripts": {
    "start": "node ./bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

const CODES = {
  reset: [0, 0],
  bold: [1, 22],
  dim: [2, 22],
  red: [31, 39],
  green: [32, 39],
  yellow: [33, 39],
  blue: [34, 39],
  magenta: [35, 39],
  cyan: [36, 39],
};

export function supportsColor(stream = process.stdout, env = process.env) {
  if (env.FORCE_COLOR === "0") return false;
  if (env.FORCE_COLOR !== undefined && env.FORCE_COLOR !== "") return true;
  if (env.NO_COLOR !== undefined && env.NO_COLOR !== "") return false;

  if (stream && typeof stream.hasColors === "function") {
    return stream.hasColors();
  }

  return Boolean(stream && stream.isTTY);
}

export function colorDepth(stream = process.stdout, env = process.env) {
  if (stream && typeof stream.getColorDepth === "function") {
    return stream.getColorDepth(env);
  }
  return supportsColor(stream, env) ? 4 : 1;
}

export function createPainter({ stream = process.stdout, env = process.env } = {}) {
  const enabled = supportsColor(stream, env);

  const paint = (name, text) => {
    if (!enabled) return String(text);
    const [open, close] = CODES[name] ?? CODES.reset;
    return `\u001b[${open}m${text}\u001b[${close}m`;
  };

  const style = {};
  for (const name of Object.keys(CODES)) {
    style[name] = (text) => paint(name, text);
  }
  style.enabled = enabled;
  return style;
}

#!/usr/bin/env node
import { createPainter, colorDepth, supportsColor } from "../lib/colors.js";

const args = process.argv.slice(2);
const c = createPainter();

if (args.includes("--no-color")) {
  process.env.NO_COLOR = "1";
}
if (args.includes("--color")) {
  process.env.FORCE_COLOR = "1";
}

const painter = createPainter();
const enabled = supportsColor();
const depth = colorDepth();

const message = args.find((arg) => !arg.startsWith("-")) ?? "Hello, terminal!";

if (!enabled) {
  console.log(message);
  process.exit(0);
}

console.log(painter.green(message));
console.log(painter.dim(`color support: yes (depth ${depth}-bit)`));

import assert from "node:assert/strict";
import { test } from "node:test";
import { createPainter, supportsColor } from "../lib/colors.js";

const tty = (hasColors) => ({ isTTY: true, hasColors });

test("disables color when NO_COLOR is set", () => {
  assert.equal(supportsColor(tty(() => true), { NO_COLOR: "1" }), false);
  assert.equal(createPainter({ stream: tty(() => true), env: { NO_COLOR: "1" } }).green("x"), "x");
});

test("FORCE_COLOR overrides a non-tty stream", () => {
  assert.equal(supportsColor({ isTTY: false }, { FORCE_COLOR: "1" }), true);
});

test("FORCE_COLOR=0 disables color", () => {
  assert.equal(supportsColor(tty(() => true), { FORCE_COLOR: "0" }), false);
});

test("uses stream.hasColors when available", () => {
  assert.equal(supportsColor(tty(() => true), {}), true);
  assert.equal(supportsColor(tty(() => false), {}), false);
});

test("wraps text in ANSI codes when enabled", () => {
  const c = createPainter({ stream: tty(() => true), env: {} });
  assert.equal(c.green("ok"), "\u001b[32mok\u001b[39m");
});

